using COMSATS.StudentPortal.Web.Data; using COMSATS.StudentPortal.Web.Models; using COMSATS.StudentPortal.Web.ViewModels; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Identity; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore;
namespace COMSATS.StudentPortal.Web.Controllers;
[Authorize(Roles = "Student")] public class ProfileController(ApplicationDbContext db, UserManager<ApplicationUser> users) : Controller { public async Task<IActionResult> Index() { var user=await db.Users.Include(x=>x.StudentProfile).ThenInclude(x=>x!.AdvisorTeacherProfile).ThenInclude(x=>x!.User).SingleAsync(x=>x.Id==users.GetUserId(User)); var history=await db.SemesterResults.Where(x=>x.Student!.ApplicationUserId==user.Id).OrderBy(x=>x.SemesterNumber).ToListAsync(); var completed=history.Where(x=>!x.IsInProgress).Sum(x=>x.CreditsEarned); return View(new ProfileViewModel { Student=user,CompletedCredits=completed,DegreeCompletionPercentage=user.TotalCreditsRequired==0?0:Math.Round(completed*100.0/user.TotalCreditsRequired,2),BatchPosition=1,BatchSize=1,SemesterHistory=history.Select(x=>new ProfileViewModel.SemesterRow(x.SemesterLabel,x.CreditsEarned,x.IsInProgress?null:x.Sgpa,x.Cgpa,x.IsInProgress?"In Progress":x.AcademicStanding.ToString(),x.IsInProgress)).ToList() }); } }
